(function(root){
function shuffle(xs,rng=Math.random){const a=[...xs];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function task(rows,mode,rng=Math.random,count=4){if(!rows.length)throw Error('Wähle mindestens eine Reihe.');if(count<4||count>7)throw Error('4–7 Spuren erlaubt');const a=rows[Math.floor(rng()*rows.length)],b=1+Math.floor(rng()*10),division=mode==='div'||mode==='mix'&&rng()<.5,answer=division?b:a*b;const pool=Array.from({length:division?10:100},(_,i)=>i+1).filter(v=>v!==answer);return{a,b,division,answer,text:division?`${a*b} ÷ ${a} = ?`:`${a} × ${b} = ?`,explanation:`${a} × ${b} = ${a*b} · ${a*b} ÷ ${a} = ${b} · ${a*b} ÷ ${b} = ${a}`,options:shuffle([answer,...shuffle(pool,rng).slice(0,count-1)],rng)}}
function bonus(seconds,duration,streak){const early=Math.max(0,Math.min(1,seconds/duration)),factor=Math.min(5,1+early*2+Math.floor(streak/3)*.25);return{early,factor,points:Math.round(100*factor),fast:early>=.55}}
const sectors=[{name:'CITY START',lanes:4,sky:'#28576c',ground:'#34505a',road:'#293941',feature:'Stadt'},{name:'KÜSTENKURVEN',lanes:5,sky:'#528fa5',ground:'#c6ad75',road:'#35444c',feature:'Küste'},{name:'WALD & BAUSTELLE',lanes:6,sky:'#6b9288',ground:'#284d3e',road:'#31413f',feature:'Wald'},{name:'BERGTUNNEL',lanes:7,sky:'#25344d',ground:'#4c5368',road:'#272d39',feature:'Tunnel'},{name:'NEON-FINALE',lanes:5,sky:'#151d3c',ground:'#222849',road:'#222a3b',feature:'Nacht'}];
const api={task,shuffle,bonus,sectors};root.RallyMath=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
